/**
 * Render the tool and prompt reference pages from a server's tools/list and
 * prompts/list responses.
 *
 * Pure: no filesystem, no server. `gen-tools.mjs` feeds it the built server's
 * lists and writes the result; `test/site-tool-reference.test.ts` at the repo
 * root feeds it the lists of the server built from `src/` and compares the
 * result with the committed pages.
 */

/** Paths are relative to `site/src/content/docs/`. */
export const TOOLS_DIR = "reference/tools";
export const PROMPTS_PAGE = "reference/prompts.md";

const GENERATED_NOTE =
  "# Generated by site/scripts/gen-tools.mjs from the server's tools/list and prompts/list. " +
  "Do not edit by hand: run `npm run build` at the repo root, then `npm run gen:tools` in site/.";

