/** Sidebar order within `reference/`, after the hand-written reference pages. */
const PROMPTS_ORDER = 90;
const TOOLS_INDEX_ORDER = 100;

const byName = (a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0);

/**
 * Escape text for Markdown outside code spans: `<` would start an HTML tag
 * (`Coin<T>`) and `*` emphasis. Code spans are left as written.
 */
function escapeText(text) {
  return text
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 === 1 ? part : part.replace(/</g, "&lt;").replace(/\*/g, "\\*")))
    .join("");
}

/** Text for one table cell: escaped, one line, pipes escaped (also in code spans). */
function cell(text) {
  return escapeText(text.trim()).replace(/\s*\n+\s*/g, " ").replace(/\|/g, "\\|");
}

const code = (value) => `\`${value}\``;

function yamlString(value) {
  return JSON.stringify(value);
}

function frontmatter({ title, description, order, label }) {
  const lines = ["---", GENERATED_NOTE, `title: ${yamlString(title)}`, `description: ${yamlString(description)}`, "sidebar:"];
  if (label) lines.push(`  label: ${yamlString(label)}`);
  lines.push(`  order: ${order}`, "---", "");
  return lines.join("\n");
}

/** Follow a local JSON pointer (`#/properties/profile/anyOf/0`) inside `root`. */
function resolveRef(ref, root) {
  if (!ref.startsWith("#/")) throw new Error(`Unsupported $ref ${ref}`);
  const target = ref
    .slice(2)
    .split("/")
    .reduce((node, key) => node?.[key.replace(/~1/g, "/").replace(/~0/g, "~")], root);
  if (target === undefined) throw new Error(`Unresolved $ref ${ref}`);
  return target;
}

function range(min, max, unit = "") {
  const u = unit ? ` ${unit}` : "";
  if (min !== undefined && max !== undefined) return `${min} to ${max}${u}`;
  if (min !== undefined) return `at least ${min}${u}`;
  if (max !== undefined) return `at most ${max}${u}`;
  return "";
}

/** A parameter's type as Markdown: primitive, enum values, union or array. */
function typeOf(schema, root) {
  if (schema.$ref) return typeOf(resolveRef(schema.$ref, root), root);
  const union = schema.anyOf ?? schema.oneOf;
  if (union) return [...new Set(union.map((s) => typeOf(s, root)))].join(" | ");
  if (schema.const !== undefined) return code(schema.const);
  if (schema.enum) return schema.enum.map((v) => code(v)).join(" | ");
  const type = Array.isArray(schema.type) ? schema.type.join(" | ") : schema.type;
  if (type === "array") {
    const items = schema.items ? typeOf(schema.items, root) : "any";
    const count = range(schema.minItems, schema.maxItems, "items");
    return `array of ${items.includes(" | ") ? `(${items})` : items}${count ? ` (${count})` : ""}`;
  }
  const bounds = [];
  const inclusive = range(schema.minimum, schema.maximum);
  if (inclusive) bounds.push(inclusive);
  if (schema.exclusiveMinimum !== undefined) bounds.push(`greater than ${schema.exclusiveMinimum}`);
  if (schema.exclusiveMaximum !== undefined) bounds.push(`less than ${schema.exclusiveMaximum}`);
  return `${type ?? "any"}${bounds.length ? ` (${bounds.join(", ")})` : ""}`;
}

function paramTable(inputSchema) {
  const properties = Object.entries(inputSchema?.properties ?? {});
  if (properties.length === 0) return "No parameters.";
  const required = new Set(inputSchema.required ?? []);
  const rows = properties.map(([name, schema]) => {
    let type = typeOf(schema, inputSchema);
    if (schema.default !== undefined) type += `, default ${code(JSON.stringify(schema.default))}`;
    return `| ${code(name)} | ${cell(type)} | ${required.has(name) ? "yes" : "no"} | ${cell(schema.description ?? "")} |`;
  });
  return ["| Parameter | Type | Required | Description |", "|---|---|---|---|", ...rows].join("\n");
}

/** Profiles holding `name`, in PROFILES order, with the default marked. */
function profileText(name, profiles, defaultProfiles) {
  const holders = Object.entries(profiles)
    .filter(([, tools]) => tools.includes(name))
    .map(([profile]) => (defaultProfiles.includes(profile) ? `${code(profile)} (default)` : code(profile)));
  return holders.length ? holders.join(", ") : "always on";
}

function toolSection(tool, profiles, defaultProfiles) {
  const facts = [];
  if (tool.title) facts.push(`- Title: ${escapeText(tool.title)}`);
  facts.push(`- Profile: ${profileText(tool.name, profiles, defaultProfiles)}`);
  const annotations = Object.entries(tool.annotations ?? {})
    .filter(([key]) => key !== "title")
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([key, value]) => code(`${key}: ${value}`));
  if (annotations.length) facts.push(`- Annotations: ${annotations.join(", ")}`);
  const meta = Object.entries(tool._meta ?? {})
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([key, value]) => code(`${key}: ${JSON.stringify(value)}`));
  if (meta.length) facts.push(`- Metadata: ${meta.join(", ")}`);
  return [`## ${tool.name}`, facts.join("\n"), escapeText((tool.description ?? "").trim()), paramTable(tool.inputSchema)].join("\n\n");
}

/** Check that GROUPS covers every listed tool exactly once and names no other. */
function groupTools(tools) {
  const listed = new Map(tools.map((t) => [t.name, t]));
  const seen = new Set();
  const problems = [];
  for (const group of GROUPS) {
    for (const name of group.tools) {
      if (seen.has(name)) problems.push(`${name} is in more than one group`);
      seen.add(name);
      if (!listed.has(name)) problems.push(`${name} (group ${group.slug}) is not in the server's tool list`);
    }
  }
  for (const name of listed.keys()) {
    if (!seen.has(name)) problems.push(`${name} has no group`);
  }
  if (problems.length) {
    throw new Error(`Tool groups in site/scripts/tool-reference.mjs are out of date:\n  ${problems.join("\n  ")}`);
  }
  return GROUPS.map((group) => ({ ...group, tools: group.tools.map((name) => listed.get(name)).sort(byName) }));
}

function groupPage(group, index, profiles, defaultProfiles) {
  const n = group.tools.length;
  const head = frontmatter({
    title: group.title,
    description: `Descriptions, profiles and parameters of the ${n} ${n === 1 ? "tool" : "tools"} in the ${group.title} group.`,
    order: TOOLS_INDEX_ORDER + 1 + index,
  });
  const parts = [...(group.intro ?? []), ...group.tools.map((t) => toolSection(t, profiles, defaultProfiles))];
  return `${head}${parts.join("\n\n")}\n`;
}

function toolsIndex(groups, profiles, defaultProfiles) {
  const all = groups.flatMap((g) => g.tools.map((tool) => ({ tool, group: g }))).sort((a, b) => byName(a.tool, b.tool));
  const profiled = new Set(Object.values(profiles).flat());
  const alwaysOn = all.filter(({ tool }) => !profiled.has(tool.name)).map(({ tool }) => code(tool.name));
  const head = frontmatter({
    title: "Tools",
    description: "Every tool the server registers, grouped by task, with its profile and parameters.",
    order: TOOLS_INDEX_ORDER,
    label: "Overview",
  });
  const intro = [
    "These pages are generated from the `tools/list` response of the server started with `SUI_TOOLS=all`.",
    `The server registers ${all.length} tools. ${all.length - alwaysOn.length} belong to one or more of the profiles ${Object.keys(profiles)
      .map((p) => code(p))
      .join(", ")}${alwaysOn.length ? `, and ${alwaysOn.join(", ")} ${alwaysOn.length === 1 ? "is" : "are"} always on` : ""}.`,
  ];
  const groupRows = groups.map((g) => `| [${g.title}](/${TOOLS_DIR}/${g.slug}/) | ${g.tools.map((t) => code(t.name)).join(", ")} |`);
  const toolRows = all.map(
    ({ tool, group }) =>
      `| [${code(tool.name)}](/${TOOLS_DIR}/${group.slug}/#${tool.name}) | ${cell(tool.title ?? "")} | [${group.title}](/${TOOLS_DIR}/${group.slug}/) | ${profileText(tool.name, profiles, defaultProfiles)} |`,
  );
  return [
    head + intro.join(" "),
    "## Groups",
    ["| Group | Tools |", "|---|---|", ...groupRows].join("\n"),
    "## All tools",
    ["| Tool | Title | Group | Profile |", "|---|---|---|---|", ...toolRows].join("\n"),
  ].join("\n\n") + "\n";
}

function promptsPage(prompts) {
  const head = frontmatter({
    title: "Prompts",
    description: "The MCP prompts the server registers, with their arguments.",
    order: PROMPTS_ORDER,
  });
  const intro = `This page is generated from the server's \`prompts/list\` response. The server registers ${prompts.length} prompts.`;
  const sections = [...prompts].sort(byName).map((prompt) => {
    const facts = prompt.title ? `- Title: ${escapeText(prompt.title)}` : "";
    const args = prompt.arguments ?? [];
    const table = args.length
      ? [
          "| Argument | Required | Description |",
          "|---|---|---|",
          ...args.map((a) => `| ${code(a.name)} | ${a.required ? "yes" : "no"} | ${cell(a.description ?? "")} |`),
        ].join("\n")
      : "No arguments.";
    return [`## ${prompt.name}`, facts, escapeText((prompt.description ?? "").trim()), table].filter(Boolean).join("\n\n");
  });
  return `${head}${[intro, ...sections].join("\n\n")}\n`;
}

/**
 * Every generated page, keyed by path relative to `site/src/content/docs/`.
 *
 * @param {{ tools: object[], prompts: object[], profiles: Record<string, readonly string[]>, defaultProfiles: readonly string[] }} input
 * @returns {Map<string, string>}
 */
export function renderReference({ tools, prompts, profiles, defaultProfiles }) {
  const groups = groupTools(tools);
  const pages = new Map();
  pages.set(`${TOOLS_DIR}/index.md`, toolsIndex(groups, profiles, defaultProfiles));
  groups.forEach((group, i) => pages.set(`${TOOLS_DIR}/${group.slug}.md`, groupPage(group, i, profiles, defaultProfiles)));
  pages.set(PROMPTS_PAGE, promptsPage(prompts));
  return pages;
}
